/*
 * Ouro HX "Sleek" theme for shadcn/ui: cool greys, glass and ink.
 * From https://ourostack.github.io/ouro-ui/voyage/. Paste it at the end of your global CSS, after the Tailwind import and
 * your current theme: its :root, .dark and @theme inline values take over. Ouro HX components
 * also need ouro-base: npx shadcn@latest add ourostack/ouro-ui/ouro-base
 * The fonts are served from https://ourostack.github.io/ouro-ui/fonts/ (SIL Open Font License; LICENSE.txt there).
 */

@font-face {
  font-family: "Geist";
  font-style: normal;
  font-display: swap;
  font-weight: 100 900;
  src: url("https://ourostack.github.io/ouro-ui/fonts/geist-5.3.0.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

@font-face {
  font-family: "Geist Mono";
  font-style: normal;
  font-display: swap;
  font-weight: 100 900;
  src: url("https://ourostack.github.io/ouro-ui/fonts/geist-mono-5.3.0.woff2") format("woff2");
