}

:root {
  --radius: 0.625rem;
  --background: oklch(0.985 0.002 250);
  --foreground: oklch(0.19 0.02 250);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.19 0.02 250);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.19 0.02 250);
  --primary: oklch(0.46 0.13 238);
  --primary-foreground: oklch(0.98 0.01 230);
  --secondary: oklch(0.955 0.004 255);
  --secondary-foreground: oklch(0.24 0.03 245);
  --muted: oklch(0.955 0.004 255);
  --muted-foreground: oklch(0.49 0.014 255);
  --accent: oklch(0.945 0.008 255);
  --accent-foreground: oklch(0.24 0.02 255);
  --destructive: oklch(0.54 0.2 27);
  --border: oklch(0.905 0.006 255);
  --input: oklch(0.87 0.008 255);
  --ring: oklch(0.6 0.13 238);
  --chart-1: oklch(0.55 0.13 238);
  --chart-2: oklch(0.64 0.1 185);
  --chart-3: oklch(0.86 0.05 230);
  --chart-4: oklch(0.62 0.16 30);
  --chart-5: oklch(0.42 0.05 250);
  --sidebar: oklch(0.97 0.003 255);
  --sidebar-foreground: oklch(0.19 0.02 250);
  --sidebar-primary: oklch(0.46 0.13 238);
  --sidebar-primary-foreground: oklch(0.98 0.01 230);
  --sidebar-accent: oklch(0.945 0.008 255);
  --sidebar-accent-foreground: oklch(0.24 0.02 255);
  --sidebar-border: oklch(0.905 0.006 255);
  --sidebar-ring: oklch(0.6 0.13 238);
