  --shadow-xs: 0 1px 2px oklch(0.19 0.02 250 / 0.06);
  --shadow-sm: 0 1px 2px oklch(0.19 0.02 250 / 0.06), 0 1px 3px oklch(0.19 0.02 250 / 0.08);
