  font-display: swap;
  font-weight: 300 800;
  src: url("https://ourostack.github.io/ouro-ui/fonts/fraunces-5.3.0.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

:root {
  color-scheme: light;
  --font-sj-display: "Fraunces", Georgia, "Times New Roman", serif;
  --font-sj-body: "Source Serif 4", Georgia, "Times New Roman", serif;
