  --sj-field: color-mix(in srgb, var(--sj-bone-lift) 94%, var(--sj-vellum));
  --sj-flour: var(--sj-vellum);
  --sj-border: color-mix(in srgb, var(--sj-charcoal) 18%, transparent);
  --sj-border-strong: color-mix(in srgb, var(--sj-charcoal) 32%, transparent);
  --sj-on-photo: var(--sj-bone);
  --sj-on-photo-muted: color-mix(in srgb, var(--sj-bone) 76%, transparent);
  --sj-on-photo-soft: color-mix(in srgb, var(--sj-bone) 62%, transparent);
  --sj-on-photo-warm: color-mix(in srgb, var(--sj-bone) 78%, var(--sj-brass));
  --sj-photo-charcoal: #211f1b;
  --sj-photo-shade: color-mix(in srgb, var(--sj-photo-charcoal) 82%, transparent);
  --sj-photo-shade-soft: color-mix(in srgb, var(--sj-photo-charcoal) 42%, transparent);
  --sj-photo-glass: color-mix(in srgb, var(--sj-bone) 10%, transparent);
