  --ouro-ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ouro-ease-drawer: cubic-bezier(0.32, 0.72, 0, 1);
  --ouro-duration-press: 160ms;
  --ouro-duration-sheet: 500ms;
}

