/*
 * Ouro HX "Cookbook" theme for shadcn/ui: spoonjoy's own look, synced from the app.
 * From https://ourostack.github.io/ouro-ui/voyage/. Paste it at the end of your global CSS, after the Tailwind import and
 * your current theme: its :root, .dark and @theme inline values take over. Ouro HX components
 * also need ouro-base: npx shadcn@latest add ourostack/ouro-ui/ouro-base
 * Fonts are not included: install Geist, Geist Mono, Fraunces, or keep your own.
 */

:root {
  color-scheme: light;
  --font-sj-display: "Fraunces", Georgia, "Times New Roman", serif;
  --font-sj-body: "Source Serif 4", Georgia, "Times New Roman", serif;
  --font-sj-ui: "IBM Plex Sans Condensed", "Avenir Next Condensed", ui-sans-serif, system-ui, sans-serif;
  --sj-bone: #fbfaf4;
  --sj-bone-lift: #fffefa;
  --sj-vellum: #e8e9df;
  --sj-charcoal: #28231d;
  --sj-charcoal-soft: #635d54;
  --sj-brass: #9b6834;
  --sj-action: #28231d;
  --sj-action-deep: #1f1b17;
  --sj-on-action: var(--sj-bone);
  --sj-action-hover: var(--sj-action-deep);
  --sj-action-disabled: #6b655c;
  --sj-on-action-disabled: var(--sj-bone);
  --sj-tomato: #a24a38;
  --sj-herb: #596a4f;
  --sj-ink: var(--sj-charcoal);
  --sj-ink-soft: var(--sj-charcoal-soft);
  --sj-paper: var(--sj-bone);
  --sj-page: var(--sj-bone);
  --sj-panel: color-mix(in srgb, var(--sj-bone-lift) 88%, transparent);
  --sj-panel-solid: var(--sj-bone-lift);
  --sj-field: color-mix(in srgb, var(--sj-bone-lift) 94%, var(--sj-vellum));
  --sj-flour: var(--sj-vellum);
  --sj-border: color-mix(in srgb, var(--sj-charcoal) 18%, transparent);
  --sj-border-strong: color-mix(in srgb, var(--sj-charcoal) 32%, transparent);
  --sj-on-photo: var(--sj-bone);
  --sj-on-photo-muted: color-mix(in srgb, var(--sj-bone) 76%, transparent);
  --sj-on-photo-soft: color-mix(in srgb, var(--sj-bone) 62%, transparent);
  --sj-on-photo-warm: color-mix(in srgb, var(--sj-bone) 78%, var(--sj-brass));
  --sj-photo-charcoal: #211f1b;
  --sj-photo-shade: color-mix(in srgb, var(--sj-photo-charcoal) 82%, transparent);
  --sj-photo-shade-soft: color-mix(in srgb, var(--sj-photo-charcoal) 42%, transparent);
  --sj-photo-glass: color-mix(in srgb, var(--sj-bone) 10%, transparent);
  --sj-photo-line: color-mix(in srgb, var(--sj-bone) 24%, transparent);
  --sj-shadow: 0 24px 80px color-mix(in srgb, var(--sj-charcoal) 14%, transparent);
  --sj-shadow-soft: 0 12px 36px color-mix(in srgb, var(--sj-charcoal) 8%, transparent);
  --sj-radius-control: 0.375rem;
  --sj-radius-small: 0.25rem;
  --sj-radius-surface: 0.5rem;
  --sj-radius-photo: 0.5rem;
  --sj-radius-hero: 0.5rem;
  --warning: #b05109;
  --warning-foreground: #ffffff;
  --ouro-spring-duration: 750ms;
  --ouro-ease-spring: linear(0, 0.0663, 0.2105, 0.3763, 0.5332, 0.6669, 0.7733, 0.8533, 0.9107, 0.9499, 0.9754, 0.9911, 1, 1.0044, 1.0061, 1.0062, 1.0055, 1.0045, 1.0035, 1.0026, 1.0018, 1.0012, 1.0008, 1, 1);
  --ouro-duration-fast: 150ms;
  --ouro-duration-base: 200ms;
  --ouro-duration-slow: 300ms;
  --ouro-press-scale: 0.97;
  --ouro-backdrop-color: #18181b;
  --ouro-backdrop-max: 0.4;
  --ouro-layer: 50;
  --ouro-ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ouro-ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ouro-ease-drawer: cubic-bezier(0.32, 0.72, 0, 1);
  --ouro-duration-press: 160ms;
  --ouro-duration-sheet: 500ms;
}

.dark {
  color-scheme: dark;
  --sj-bone: #f2eee6;
  --sj-bone-lift: #282522;
  --sj-vellum: #34302b;
  --sj-charcoal: #1f1d1a;
  --sj-charcoal-soft: #c8c0b4;
  --sj-brass: #c4945c;
  --sj-action: #b9854b;
  --sj-action-deep: #95683a;
  --sj-on-action: var(--sj-charcoal);
  --sj-action-hover: #cc9a62;
  --sj-action-disabled: #463d33;
  --sj-on-action-disabled: var(--sj-charcoal-soft);
  --sj-tomato: #e58263;
  --sj-herb: #a4b578;
  --sj-ink: var(--sj-bone);
  --sj-ink-soft: var(--sj-charcoal-soft);
  --sj-paper: var(--sj-charcoal);
  --sj-page: #1e1c19;
  --sj-panel: color-mix(in srgb, var(--sj-bone-lift) 84%, transparent);
  --sj-panel-solid: var(--sj-bone-lift);
  --sj-field: color-mix(in srgb, var(--sj-charcoal) 82%, var(--sj-vellum));
  --sj-flour: var(--sj-vellum);
  --sj-border: color-mix(in srgb, var(--sj-bone) 16%, transparent);
  --sj-border-strong: color-mix(in srgb, var(--sj-bone) 28%, transparent);
  --sj-on-photo: #f1e6d3;
  --sj-on-photo-muted: color-mix(in srgb, var(--sj-on-photo) 76%, transparent);
  --sj-on-photo-soft: color-mix(in srgb, var(--sj-on-photo) 62%, transparent);
  --sj-on-photo-warm: color-mix(in srgb, var(--sj-on-photo) 78%, var(--sj-brass));
  --sj-photo-charcoal: #1d1915;
  --sj-photo-shade: color-mix(in srgb, var(--sj-photo-charcoal) 84%, transparent);
  --sj-photo-shade-soft: color-mix(in srgb, var(--sj-photo-charcoal) 46%, transparent);
  --sj-photo-glass: color-mix(in srgb, var(--sj-on-photo) 10%, transparent);
  --sj-photo-line: color-mix(in srgb, var(--sj-on-photo) 22%, transparent);
  --sj-shadow: 0 28px 90px color-mix(in srgb, var(--sj-photo-charcoal) 56%, transparent);
  --sj-shadow-soft: 0 16px 44px color-mix(in srgb, var(--sj-photo-charcoal) 42%, transparent);
  --warning: #fbbf24;
  --warning-foreground: #000000;
  --ouro-backdrop-color: #000000;
}

:root, .dark {
  --background: var(--sj-paper);
  --foreground: var(--sj-ink);
  --popover: var(--sj-panel-solid);
  --popover-foreground: var(--sj-ink);
  --primary: var(--sj-brass);
  --primary-foreground: var(--sj-paper);
  --secondary: var(--sj-flour);
  --secondary-foreground: var(--sj-ink);
  --muted: var(--sj-flour);
  --muted-foreground: var(--sj-ink-soft);
  --accent: var(--sj-flour);
  --accent-foreground: var(--sj-ink);
  --destructive: var(--sj-tomato);
  --destructive-foreground: var(--sj-paper);
  --success: var(--sj-herb);
  --success-foreground: var(--sj-paper);
  --border: var(--sj-border);
  --input: var(--sj-border-strong);
  --ring: var(--sj-brass);
  --radius: var(--sj-radius-control);
}

:root, .dark {
  --card: var(--sj-panel-solid);
  --card-foreground: var(--sj-ink);
  --chart-1: var(--sj-brass);
  --chart-2: var(--sj-herb);
  --chart-3: var(--sj-brass);
  --chart-4: var(--sj-tomato);
  --chart-5: var(--sj-ink-soft);
  --sidebar: var(--sj-page);
  --sidebar-foreground: var(--sj-ink);
  --sidebar-primary: var(--sj-brass);
  --sidebar-primary-foreground: var(--sj-paper);
  --sidebar-accent: var(--sj-flour);
  --sidebar-accent-foreground: var(--sj-ink);
  --sidebar-border: var(--sj-border);
  --sidebar-ring: var(--sj-brass);
  --font-heading: var(--font-sj-display);
  --shadow-xs: 0 1px 2px color-mix(in srgb, var(--sj-charcoal) 8%, transparent);
  --shadow-sm: 0 1px 3px color-mix(in srgb, var(--sj-charcoal) 10%, transparent);
  --shadow-md: var(--sj-shadow-soft);
  --shadow-lg: var(--sj-shadow-soft);
  --shadow-xl: var(--sj-shadow);
}

@theme inline {
  --font-sans: "Geist", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Geist Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;
